import{_ as a,o as i,c as s,a5 as o}from"./chunks/framework.BwlBv862.js";const m=JSON.parse('{"title":"Registro del candidato TikTools 4.2.1-rc.1","description":"","frontmatter":{"title":"Registro del candidato TikTools 4.2.1-rc.1","docId":"releases.4.2.1-rc.1","translationKey":"releases.4.2.1-rc.1","locale":"es","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"f2b9e975511584a1a6156af8326d7603d73be54f10c97d7e46ed385def4755f6","translationRevision":"2ad2020888e2b339a9b8b85e8164054339525879d6c5d052cc2c53a96dc9c3f3","order":10},"headers":[],"relativePath":"es/releases/4.2.1-rc.1.md","filePath":"es/releases/4.2.1-rc.1.md","lastUpdated":1794611623000}'),r={name:"es/releases/4.2.1-rc.1.md"};function n(t,e,l,c,d,p){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="tiktools-421-rc1" tabindex="-1">TikTools 4.2.1-rc.1 <a class="header-anchor" href="#tiktools-421-rc1" aria-label="Permalink to &quot;TikTools 4.2.1-rc.1 {#tiktools-421-rc1}&quot;">​</a></h1><h2 id="goal-status-and-prerequisites" tabindex="-1">Objetivo, estado y requisitos <a class="header-anchor" href="#goal-status-and-prerequisites" aria-label="Permalink to &quot;Objetivo, estado y requisitos {#goal-status-and-prerequisites}&quot;">​</a></h2><p>Usa este registro histórico para reproducir los problemas de recuperación Cloud, Teams y AppImage Linux investigados en RC1. Describe la aplicación <code>338495a9</code> y, por separado, el backend <code>6a69c99</code>. Estas notas no acreditan la disponibilidad actual de descargas RC1. Revisa los <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">artefactos publicados</a> antes de elegir un instalador.</p><p>El candidato registrado utilizó AppImage, DEB y paquetes portátiles Linux compilados localmente mientras Actions estaba deshabilitado. No incluyó un instalador Windows recién compilado. Conserva una copia de seguridad y un perfil aislado para probar la migración. La colaboración y la recuperación Cloud por sección siguen siendo experimentales.</p><h2 id="changes-in-this-candidate" tabindex="-1">Cambios del candidato <a class="header-anchor" href="#changes-in-this-candidate" aria-label="Permalink to &quot;Cambios del candidato {#changes-in-this-candidate}&quot;">​</a></h2><ul><li>Settings conserva cuenta, sesión y diagnósticos; Plugins reúne catálogo, búsqueda, Changes e instalación. Las plantillas y perfiles permanecen en Automations.</li><li>El panel Changes distingue un fallo de comparación de un resultado vacío correcto. La sección Plugins envía sus selecciones y ajustes, conservando las demás colas y las descargas en caché.</li><li>La migración admite que falte el directorio implícito de plugins incluidos, mantiene estrictas las rutas explícitas e identifica los paquetes ausentes para una reparación revisada. Conserva ediciones pendientes y conflictos.</li><li>Teams diferencia registrar este PC como host de seleccionar el host de otro equipo. Las invitaciones por apodo quedan ligadas al destinatario elegido y siguen requiriendo aprobación del host.</li><li>La ayuda opcional sigue el estado de configuración. El empaquetado Linux incluye helpers WebKit, plugins GStreamer y su scanner para comprobar después la reproducción.</li></ul><h2 id="reproduce-and-inspect-the-expected-result" tabindex="-1">Reproducir y comprobar el resultado esperado <a class="header-anchor" href="#reproduce-and-inspect-the-expected-result" aria-label="Permalink to &quot;Reproducir y comprobar el resultado esperado {#reproduce-and-inspect-the-expected-result}&quot;">​</a></h2><ol><li>Anota la versión mostrada y el sistema operativo. Abre Plugins → Changes y conserva el error exacto y el identificador de petición si falla la carga.</li><li>En el perfil copiado, previsualiza la migración y revisa los IDs exactos antes de reparar paquetes ausentes. Repite la vista previa; las ediciones pendientes y los conflictos deben conservarse.</li><li>En Teams, registra el PC actual antes de probar Start. Seleccionar el host de otro equipo no debe autorizar el arranque de este.</li><li>Comprueba por separado el inicio del AppImage y el audio/vídeo. Llegar al frontend no acredita reproducción multimedia correcta.</li></ol><p>La búsqueda por apodo y las invitaciones ligadas al destinatario requieren el backend <code>6a69c99</code> y la migración <code>20261113000001_remote_invitation_recipients.sql</code>. Instalar este candidato no despliega ese backend.</p><h2 id="recovery-and-evidence-limits" tabindex="-1">Recuperación y límites de la evidencia <a class="header-anchor" href="#recovery-and-evidence-limits" aria-label="Permalink to &quot;Recuperación y límites de la evidencia {#recovery-and-evidence-limits}&quot;">​</a></h2><p>Si falla una comparación, conserva el motivo nativo y reintenta mediante el panel admitido. No elimines el estado pendiente ni deduzcas una migración correcta de una comprobación de compatibilidad. Recoge versión, acción y diagnósticos redactados según la <a href="./../user/preferences/troubleshooting.html">guía de solución de problemas</a>.</p><p>El registro original informa de pruebas de frontend, sincronización, aislamiento de destinatarios y dos hosts nativos/relay en su revisión. Son resultados fechados, no una validación nueva de producción. No se identificó al responsable del bloqueo SQLite histórico. En RC1 faltaban los adaptadores Cloud de Variables y Overlays, y Automations comparaba una referencia local. Consulta las <a href="./4.2.1-rc.3.html">notas posteriores</a> y la <a href="./../user/cloud/changes.html">guía actual de Changes</a>.</p><p>El <a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.1.md" target="_blank" rel="noreferrer">registro original</a> se conserva como evidencia fechada. Vuelve al <a href="./">índice de versiones</a>.</p>',13)])])}const h=a(r,[["render",n]]);export{m as __pageData,h as default};
